html:
{% set mode = doc.language_mode or "Bilingual" %}
{% set layout = doc.bilingual_layout or "Side by Side" %}
<div class="template-preview {% if doc.table_print_style == 'Borderless Layout' %}template-borderless-tables{% endif %}">
  <div class="preview-note">
    <strong>{{ _("Template Preview") }}</strong> — {{ _("This preview shows layout and template variables before the template is made available to employees. Variables remain as placeholders until an Employee Letter Request is issued.") }}
  </div>

  <table class="meta-table">
    <tr><td class="meta-label">{{ _("Template") }}</td><td>{{ doc.template_name }}</td><td class="meta-label">{{ _("Company") }}</td><td>{{ doc.company }}</td></tr>
    <tr><td class="meta-label">{{ _("Type") }}</td><td>{{ doc.template_type }}</td><td class="meta-label">{{ _("Language") }}</td><td>{{ mode }}{% if mode == "Bilingual" %} — {{ layout }}{% endif %}</td></tr>
    <tr><td class="meta-label">{{ _("Active") }}</td><td>{{ _("Yes") if doc.is_active else _("No") }}</td><td class="meta-label">{{ _("Available for Employee Request") }}</td><td>{{ _("Yes") if doc.available_for_employee_request else _("No") }}</td></tr>
    <tr><td class="meta-label">{{ _("Validity") }}</td><td>{% if doc.has_expiry %}{{ doc.validity_days }} {{ _("days") }}{% else %}{{ _("No expiry") }}{% endif %}</td><td class="meta-label">{{ _("Final Document") }}</td><td>{{ doc.final_document_method }}{% if doc.final_document_method == "System Generated PDF" %}<br><span class="muted">{{ _("Generated on demand; no PDF attachment is stored") }}</span>{% endif %}</td></tr>
    {% if doc.has_expiry %}<tr><td class="meta-label">{{ _("After Expiry") }}</td><td colspan="3">{{ doc.expired_document_policy or "Historical Copy with EXPIRED Watermark" }}</td></tr>{% endif %}
    <tr><td class="meta-label">{{ _("Signature") }}</td><td>{{ _("Required") if doc.requires_signature else _("Not required") }}</td><td class="meta-label">{{ _("Stamp") }}</td><td>{{ _("Required") if doc.requires_stamp else _("Not required") }}</td></tr>
    <tr><td class="meta-label">{{ _("Table Style") }}</td><td colspan="3">{{ doc.table_print_style or "Standard Borders" }}</td></tr>
    <tr><td class="meta-label">{{ _("Fee Policy") }}</td><td>{{ doc.fee_policy }}</td><td class="meta-label">{{ _("Fee Amount") }}</td><td>{% if doc.fee_policy != "No Fee" %}{{ doc.fee_amount }} {{ frappe.db.get_value("Company", doc.company, "default_currency") or "" }}{% else %}0{% endif %}</td></tr>
  </table>

  {% macro english_single() %}
    <div class="letter-left">
      {% if doc.letter_subject_english %}<div class="letter-subject">{{ doc.letter_subject_english }}</div>{% endif %}
      <div class="letter-body">{{ (doc.template_text_english or "") | safe }}</div>
    </div>
  {% endmacro %}
  {% macro arabic_single() %}
    <div class="letter-right">
      {% if doc.letter_subject_arabic %}<div class="letter-subject">{{ doc.letter_subject_arabic }}</div>{% endif %}
      <div class="letter-body">{{ (doc.template_text_arabic or "") | safe }}</div>
    </div>
  {% endmacro %}

  {% if (doc.content_mode or "Single Content") == "Sections" %}
    {% if doc.letter_subject_english or doc.letter_subject_arabic %}
      {% if mode == "Bilingual" and layout == "Side by Side" %}
        <table class="letter-table"><tr><td class="letter-left bilingual-divider"><div class="letter-subject">{{ doc.letter_subject_english or "" }}</div></td><td class="letter-right"><div class="letter-subject">{{ doc.letter_subject_arabic or "" }}</div></td></tr></table>
      {% elif mode == "Arabic Only" %}<div class="letter-subject letter-right">{{ doc.letter_subject_arabic or "" }}</div>
      {% else %}<div class="letter-subject letter-left">{{ doc.letter_subject_english or "" }}</div>{% endif %}
    {% endif %}
    {% for section in doc.sections %}
      <div class="section-wrap {% if section.page_break_before %}section-page-break{% endif %} {% if section.keep_together %}section-keep{% endif %}">
        {% if mode == "Arabic Only" %}
          <div class="letter-right">{% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}<div class="letter-body">{{ (section.content_arabic or "") | safe }}</div></div>
        {% elif mode == "English Only" %}
          <div class="letter-left">{% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}<div class="letter-body">{{ (section.content_english or "") | safe }}</div></div>
        {% elif layout == "Side by Side" %}
          <table class="section-table"><tr><td class="letter-left bilingual-divider">{% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}<div class="letter-body">{{ (section.content_english or "") | safe }}</div></td><td class="letter-right">{% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}<div class="letter-body">{{ (section.content_arabic or "") | safe }}</div></td></tr></table>
        {% elif layout == "Arabic then English" %}
          <div class="letter-right">{% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}<div class="letter-body">{{ (section.content_arabic or "") | safe }}</div></div><div class="letter-separator"></div><div class="letter-left">{% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}<div class="letter-body">{{ (section.content_english or "") | safe }}</div></div>
        {% else %}
          <div class="letter-left">{% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}<div class="letter-body">{{ (section.content_english or "") | safe }}</div></div><div class="letter-separator"></div><div class="letter-right">{% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}<div class="letter-body">{{ (section.content_arabic or "") | safe }}</div></div>
        {% endif %}
      </div>
    {% endfor %}
  {% else %}
    {% if mode == "Arabic Only" %}{{ arabic_single() }}
    {% elif mode == "English Only" %}{{ english_single() }}
    {% elif layout == "Arabic then English" %}{{ arabic_single() }}<div class="letter-separator"></div>{{ english_single() }}
    {% elif layout == "English then Arabic" %}{{ english_single() }}<div class="letter-separator"></div>{{ arabic_single() }}
    {% else %}<table class="letter-table"><tr><td class="bilingual-divider">{{ english_single() }}</td><td>{{ arabic_single() }}</td></tr></table>{% endif %}
  {% endif %}

  {% if doc.requires_signature or doc.requires_stamp %}
    <div class="preview-signatory">
      {% if doc.requires_signature %}<div class="preview-sign-box">{{ _("Signature position") }}<br>مكان التوقيع</div>{% endif %}
      {% if doc.requires_stamp %}<div class="preview-sign-box">{{ _("Stamp position") }}<br>مكان الختم</div>{% endif %}
      {% if doc.default_signatory %}<div style="margin-top:8px"><strong>{{ _("Default Signatory") }}:</strong> {{ doc.default_signatory }}</div>{% endif %}
    </div>
  {% endif %}
</div>

css:
.template-preview { font-family: Arial, sans-serif; color:#111; font-size:10.5pt; line-height:1.55; }
.preview-note { border:1px dashed #999; padding:8px 10px; margin-bottom:14px; color:#555; background:#fafafa; }
.meta-table { width:100%; border-collapse:collapse; margin-bottom:18px; font-size:9.5pt; }
.meta-table td { border:1px solid #ddd; padding:6px 8px; vertical-align:top; }
.meta-label { font-weight:700; width:18%; background:#f7f7f7; }
.letter-table, .section-table { width:100%; border-collapse:collapse; table-layout:fixed; }
.letter-table td, .section-table td { width:50%; vertical-align:top; }
.letter-left { direction:ltr; text-align:left; padding-right:13px; }
.letter-right { direction:rtl; text-align:right; padding-left:13px; font-family:Tahoma, Arial, sans-serif; }
.bilingual-divider { border-right:1px solid #ddd; }
.letter-subject { text-align:center; font-weight:700; font-size:13pt; margin:8px 0 16px; }
.letter-body { white-space:normal; }
.section-wrap { margin:0 0 14px; }
.section-title { font-weight:700; margin:0 0 6px; font-size:11.5pt; }
.section-page-break { page-break-before:always; }
.section-keep { page-break-inside:avoid; }
.letter-separator { border-top:1px solid #ddd; margin:20px 0; }
.rule-yes { font-weight:700; }

.preview-signatory { margin-top:28px; page-break-inside:avoid; }
.preview-sign-box { display:inline-block; min-width:140px; min-height:52px; border:1px dashed #aaa; padding:8px; margin-right:12px; text-align:center; color:#777; vertical-align:top; }

.muted { color:#666; font-size:8.5pt; }

.template-borderless-tables .letter-body table, .template-borderless-tables .letter-body thead, .template-borderless-tables .letter-body tbody, .template-borderless-tables .letter-body tr, .template-borderless-tables .letter-body th, .template-borderless-tables .letter-body td { border:0 !important; box-shadow:none !important; }\n.template-borderless-tables .letter-body th, .template-borderless-tables .letter-body td { background:transparent !important; }
